#include <stdio.h>

static int inChain[1005];

int main(void) {
    int N, C;
    if (scanf("%d %d", &N, &C) != 2) return 0;

    for (int i = 0; i < C; i++) {
        int P, I;
        if (scanf("%d %d", &P, &I) != 2) break;
        for (int j = 0; j < I; j++) {
            int x;
            if (scanf("%d", &x) != 1) break;
            inChain[x] = 1;  /* x foi infectado por algum humano */
        }
    }

    /* Paciente(s) Zero: quem nunca aparece em nenhuma cadeia de transmissão */
    for (int v = 1; v <= N; v++) {
        if (!inChain[v]) {
            printf("%d\n", v);
        }
    }

    return 0;
}
